def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    alive_count = 1 + len(alive_opponents)
    capacity = int(supply // WATER_REQ)
    shortage = max(0, alive_count - capacity)

    prev_bids = []
    urgent_opps = 0
    rich_opps = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 90:
            rich_opps += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opps += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    desperation = 0
    if hp <= 2:
        desperation += 3
    elif hp <= 4:
        desperation += 2
    elif hp <= 6:
        desperation += 1
    if no_water_days >= 2:
        desperation += 3
    elif no_water_days >= 1:
        desperation += 2

    if budget <= 0:
        return 0.0

    if len(alive_opponents) == 0:
        return float(min(budget, 18.0 if hp > 4 else 45.0))

    base = 0.0

    if shortage <= 0:
        if desperation >= 3:
            base = 52.0
        else:
            base = 16.0
    elif shortage == 1:
        if desperation >= 4:
            base = max(88.0, highest_prev + 2.0)
        elif desperation >= 2:
            base = max(68.0, avg_prev * 0.78)
        else:
            base = max(36.0, avg_prev * 0.45)
    else:
        if desperation >= 4:
            base = max(102.0, highest_prev + 3.0)
        elif desperation >= 2:
            base = max(82.0, highest_prev * 0.9)
        else:
            base = max(58.0, avg_prev * 0.6)

    if highest_prev >= 120:
        if desperation <= 1 and shortage <= 1:
            base = min(base, 42.0)
        elif desperation >= 4:
            base = max(base, 108.0)

    if rich_opps >= 2 and shortage >= 1 and desperation >= 2:
        base += 6.0
    if urgent_opps >= 2 and shortage >= 1:
        base += 5.0

    if day >= 8:
        if hp > 5 and shortage <= 1:
            base -= 8.0
        else:
            base += 6.0

    reserve = 0.0
    if hp <= 3:
        reserve = 0.0
    elif day <= 6:
        reserve = DAILY_SALARY * 2.0
    else:
        reserve = DAILY_SALARY * 1.0

    cap = budget - reserve
    if cap < 0:
        cap = budget * 0.65
    if desperation >= 4:
        cap = budget

    bid = min(base, cap, budget)

    if desperation >= 4:
        bid = max(bid, min(budget, max(95.0, highest_prev + 1.0)))
    elif desperation >= 2 and shortage >= 1:
        bid = max(bid, min(budget, 72.0))

    if shortage <= 0 and desperation == 0:
        bid = min(bid, 22.0)

    if bid < 0:
        bid = 0.0

    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 50.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_bid * 1.05
    else:
        bid = DAILY_SALARY * 0.6

    if my_status['hp'] < 5:
        bid = bid * 1.2

    return float(min(my_status['budget'], max(bid, 40.0)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If no opponents alive, conserve.
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])

    # Determine pressure from yesterday.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Supply-based urgency: more supply reduces competition need.
    supply = day_context.get('supply', 0.0)
    # Convert to int index safely if we ever use arrays; here we just compute thresholds.
    supply_level = int(max(MIN_SUPPLY, min(MAX_SUPPLY, float(supply))))

    # Base bid logic.
    # If my HP is critical, I bid to secure water.
    if my_status['hp'] <= 2:
        target = max(DAILY_SALARY * 0.85, highest_prev_bid + 2.0)
        return min(my_status['budget'], target)

    # If my HP is low-ish, bid closer to yesterday leaders.
    if my_status['hp'] <= 4:
        target = max(DAILY_SALARY * 0.65, highest_prev_bid * 0.9)
        return min(my_status['budget'], target)

    # My HP is healthy: bid depends on competition pressure and supply.
    # When supply is scarce, increase bid slightly above second-highest to beat most.
    scarce = supply_level <= 18
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        # Opponents were extremely aggressive yesterday.
        if scarce:
            target = max(DAILY_SALARY * 0.75, second_prev_bid + 6.0)
        else:
            target = max(DAILY_SALARY * 0.65, second_prev_bid + 4.0)
        return min(my_status['budget'], target)

    # Moderate pressure: bid enough to likely win without burning budget.
    if scarce:
        target = max(DAILY_SALARY * 0.55, second_prev_bid + 3.0)
    else:
        target = max(DAILY_SALARY * 0.48, second_prev_bid + 2.0)

    # If we have many consecutive no-water days, we must secure.
    if my_status.get('no_water_days', 0) >= 2:
        target = max(target, DAILY_SALARY * 0.7)

    return min(my_status['budget'], target)
